/* Character positions from Figma frame 3:45. */
const ideaGlyphData = [
"",
"",
"",
"",
].join('');
// These coordinates come directly from the editable Figma character layers.
const ideaStage = document.createElement('div');
ideaStage.className = 'idea-background-stage';
ideaStage.setAttribute('aria-hidden', 'true');
const ideaField = document.createElement('div');
ideaField.className = 'idea-character-field';
ideaField.dataset.nodeId = '190:48302';
const ideaBytes = atob(ideaGlyphData);
const ideaGlyphs = document.createDocumentFragment();
for (let i = 0; i < ideaBytes.length; i += 8) {
  const read = offset => ideaBytes.charCodeAt(i + offset);
  const x = (read(0) | read(1) << 8) / 10;
  const y = (read(2) | read(3) << 8) / 10;
  const size = (read(4) | read(5) << 8) / 100;
  const glyph = document.createElement('span');
  glyph.textContent = String.fromCharCode(read(7));
  glyph.style.cssText = `left:${x}px;top:${y}px;font-size:${size}px;opacity:${read(6) / 100};width:${size * .96875}px;line-height:${size * .926}px`;
  ideaGlyphs.append(glyph);
}
ideaField.append(ideaGlyphs);
ideaStage.append(ideaField);
document.body.prepend(ideaStage);
function fitAboutBackground() { ideaStage.style.transform = `scale(${window.innerWidth / 1920})`; }
fitAboutBackground();
window.addEventListener('resize', fitAboutBackground);
if (new URLSearchParams(location.search).has('design-check')) ideaField.style.animation = 'none';